-- CIDM-11621 MDM ID & IRN update prod issue - one time data cleanup
/*
-- Issue Description: 
   Person Medication Refill one-Time parentid newly added column update 

	Root cause: As a part of 06/25/2026 Prod build one bug was introduced which caused errors while updating the MDM ID & IRN in CJAMS database.
	Fix Provided: 
	Regression Impacts: Validated as a part of code fix.
	Is Code fix Required?: (Yes/No) Yes
		Code fix ticket#: (If Yes) CIDM-11571 Deployed in production on 07/16/2026
*/
 
-- Update person table -> cisclientid
update person p
set cisclientid = (select btrim(pn.personidentifiervalue)
						from personidentifier pn 
				   where pn.personid = p.personid 
				        and pn.activeflag = 1    
				        and pn.personidentifiertypekey = 'IRN'
				   order by pn.insertedon desc
				   limit 1
				   ),
	updatedby = 'CIDM-11621',
	updatedon = now()
where activeflag = 1
	and insertedon::date >= '2026-06-25'::date
	and (cisclientid is null or btrim(cisclientid) = '' )
	and (select count(*)
			from personidentifier pn 
		where pn.personid = p.personid 
	        and pn.activeflag = 1    
	        and pn.personidentifiertypekey = 'IRN'
	    ) > 0    
;	


